import { partition } from "./src/array/partition.js";
{
{
{
const arr = [10, 20, 30, 40, 50];
        const indices = [];
        const [result] = partition(arr, (value, index) => {
            indices.push(index);
            return index % 2 === 0;
        });
        expect(indices).toEqual([0, 1, 2, 3, 4]);
        expect(result).toEqual([10, 30, 50]);
}
}
