import { expect, expectTypeOf, assertType } from "./test/expect-shim.mjs";
import { partition } from "./src/array/partition.js";
{
{
{
const arr = [1, 2, 3, 4, 5];
        const arrays = [];
        const [evens] = partition(arr, (value, index, array) => {
            arrays.push(array);
            return value % 2 === 0;
        });
        expect(evens).toEqual([2, 4]);
        expect(arrays).toHaveLength(5);
        arrays.forEach(array => {
            expect(array).toBe(arr);
        });
}
}
}

